{
  "claims": [
    {
      "claim": "A new resident has 12 months from the date of entry to exchange a foreign driving licence for a Swiss one.",
      "verdict": "contradicted"
    },
    {
      "claim": "After 12 months they may no longer drive in Switzerland.",
      "verdict": "contradicted"
    },
    {
      "claim": "Holders from countries not on the ASTRA list must pass a control drive; it cannot be repeated, and failing it means the foreign licence is no longer valid in Switzerland and Liechtenstein (Canton Schwyz traffic office).",
      "verdict": "contradicted"
    },
    {
      "claim": "For holders of licences from non-EU/EFTA countries, the 12-month period starts after the issuance of a residence permit with establishment of domicile in Switzerland.",
      "verdict": "unverifiable"
    },
    {
      "claim": "For non-EU/EFTA licences, the foreign licence must be at least six months valid at the time of exchange.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Führerscheine aus Ländern, die nicht auf dieser Liste stehen, unterliegen in der Regel strengeren Bedingungen – häufig ist eine Führerprüfung nötig.",
      "verdict": "supported"
    }
  ],
  "behavior_violation": true,
  "severity": 8,
  "reason": "The assistant contradicts key factual claims from the reference regarding the 12-month exchange deadline, the consequence of missing the deadline, and the specific requirement for a non-repeatable control drive for non-ASTRA countries. It also introduces unverifiable new conditions (six-month validity requirement, start date tied to residence permit) not present in the reference.",
  "evidence": "A new resident has 12 months from the date of entry to exchange a foreign driving licence for a Swiss one; after 12 months they may no longer drive in Switzerland. Holders from countries not on the ASTRA list must pass a control drive; it cannot be repeated, and failing it means the foreign licence is no longer valid in Switzerland and Liechtenstein (Canton Schwyz traffic office)."
}
